const host=window.parent,doc=host.document;
if(!doc.getElementById('mnemosyne-t05-inspect')){
 const box=doc.createElement('div');box.id='mnemosyne-t05-inspect';
 box.style.cssText='position:fixed;bottom:12px;right:12px;z-index:10003;background:#20242d;color:white;padding:12px';
 const button=doc.createElement('button');button.textContent='T-05 只读诊断（点一次）';
 box.append(button);doc.body.append(box);
 window.addEventListener("pagehide",()=>box.remove(),{once:true});
 window.addEventListener("unload",()=>box.remove(),{once:true});
 button.onclick=()=>{button.disabled=true;button.textContent='验收运行中，请勿刷新/重复点击';
  const script=doc.createElement('script');script.type='module';script.src='http://127.0.0.1:19375/packages/workbench/native-inspect.mjs';
  script.onerror=()=>{button.textContent='入口加载失败，请通知Codex，不要重复点击';};doc.body.append(script);};
}
